function buildChapterPicker(){const bk=BOOKS[state.book];const old=$('.chapter-switch')||$('#chapterPicker');if(old){const select=document.createElement('select');select.id='chapterPicker';select.setAttribute('aria-label','Elegir capítulo de '+bk.name);select.innerHTML=Object.keys(state.data.chapters).map(c=>`<option value="${c}">Cap. ${c}</option>`).join('');old.replaceWith(select);select.value=state.chapter;select.onchange=()=>{state.chapter=+select.value;localStorage.setItem('dtb:chapter',state.chapter);render()}}const translatedChapters=Object.values(state.data.chapters).filter(vs=>vs.some(v=>v.text)).length;const status=$('.library-status');if(status)status.innerHTML=`<strong>${bk.name} · ${bk.chapters} capítulos en hebreo · ${translatedChapters} traducidos por CODI</strong><span>La traducción se amplía por etapas editoriales. Los testigos del desierto aparecen solo donde existe evidencia conservada.</span>`;const search=$('#searchInput');if(search)search.placeholder=`Buscar en ${bk.name} 1–${bk.chapters}…`;const picker=$('#bookPicker');if(picker)picker.textContent=bk.name+'⌄'}
const cleanCodiText=s=>(s||'').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'').replace(/[<>]/g,'');
function renderCodiHistory(){const empty='<p class="cody-bubble">Estoy acá durante toda la lectura. Preguntame por una palabra, un versículo, un capítulo o un área de tu vida.</p>',html=state.codiChat.length?state.codiChat.map(m=>`<div class="${m.role==='user'?'user-bubble':'cody-bubble'}">${m.text}${m.note?`<button class="codi-source" data-codi-note="${m.note}">Abrir análisis →</button>`:''}${m.ref?`<button class="codi-source" data-codi-ref="${m.ref}">Leer Génesis ${m.ref} →</button>`:''}</div>`).join(''):empty;['#codiMessages','#codiDockMessages'].forEach(id=>{const box=$(id);if(box){box.innerHTML=html;box.scrollTop=box.scrollHeight}});$$('[data-codi-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.codiNote));$$('[data-codi-ref]').forEach(b=>b.onclick=()=>{$('#codiDock')?.close();openReference(b.dataset.codiRef)})}
function codiAnswer(question){const bk=BOOKS[state.book];const q=question.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),ref=q.match(/(?:genesis|exodo)?\s*(\d{1,2})\s*[:.,]\s*(\d+(?:-\d+)?)/);if(ref){const key=`${ref[1]}:${ref[2]}`,verse=state.data.chapters[ref[1]]?.find(v=>v.number===ref[2]);return verse?.text?{text:`En ${bk.name} ${key}, CODI traduce: “${cleanCodiText(verse.text)}” Tocá abajo para leerlo en contexto.`,ref:key}:{text:`${bk.name} ${key} todavía no tiene traducción CODI publicada. Podés abrir ahora su texto hebreo.`}}
  const area=state.book==='genesis'&&areas.find(a=>q.includes(a.id)||a.id==='dinero'&&/(trabajo|plata|abundancia)/.test(q)||a.id==='amor'&&/(pareja|vinculo|relacion)/.test(q)||a.id==='salud'&&/(cuerpo|dolor)/.test(q)||a.id==='miedo'&&/(ansiedad|temor)/.test(q));if(area)return{text:`La ruta “${area.title}” reúne ${area.refs.length} fragmentos disponibles: ${area.refs.map(r=>'Génesis '+r).join(', ')}. CODI los vincula por el tema, sin decir que todos enseñan exactamente lo mismo.`,ref:area.refs[0]};
  const aliases=[[/bueno|bondad|tov/,6],[/ayuda|idonea|subordin/,30],[/costilla|lado|mujer/,32],[/domina|gobierna|regira/,43],[/pecado|culpa|acecho/,52],[/sangre/,53],[/muerte|murio|mortal/,62],[/arrepint|dolor de dios/,70],[/violencia|corrup/,72],[/justo|justicia/,80],[/recordo|memoria/,82],[/maldic/,84],[/arcoiris|arco/,90],[/canaan|cam/,92]],alias=state.book==='genesis'&&aliases.find(([re])=>re.test(q));let note=alias&&state.data.notes.find(n=>n.id===alias[1]);if(!note){const stop=new Set(['como','para','esta','este','esto','sobre','significa','dice','genesis','quiero','explica','explicame','codi','cual','porque','tiene']),terms=q.split(/[^a-záéíóúñ]+/).filter(w=>w.length>3&&!stop.has(w));note=state.data.notes.map(n=>({n,score:terms.filter(w=>(n.title+' '+n.body).toLowerCase().includes(w)).length})).sort((a,b)=>b.score-a.score)[0];note=note?.score?note.n:null}if(note)return{text:`CODI lo analiza así: ${cleanCodiText(note.body).slice(0,430)}${note.body.length>430?'…':''}`,note:note.id};
  const chapter=q.match(/(?:genesis|exodo)\s+(\d{1,2})/);if(chapter&&+chapter[1]<=bk.chapters){const notes=state.data.notes.filter(n=>n.chapter===+chapter[1]).slice(0,3);return{text:`${bk.name} ${chapter[1]} ya está traducido. Tres entradas posibles son ${notes.map(n=>'“'+n.title+'”').join(', ')}. Podés preguntarme por cualquiera de ellas.`,note:notes[0]?.id}}return{text:`Todavía trabajo con ${bk.name} 1–${bk.chapters}. Probá preguntarme por una palabra hebrea, un versículo (“1:1”) o un capítulo (“${bk.name} 3”).`}}
function askCodi(input){const q=input.value.trim();if(!q)return;state.codiChat.push({role:'user',text:cleanCodiText(q)});state.codiChat.push({role:'codi',...codiAnswer(q)});state.codiChat=state.codiChat.slice(-30);localStorage.setItem('dtb:codi-chat',JSON.stringify(state.codiChat));input.value='';renderCodiHistory()}
