function notesIn(t){return (t||'').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,m=>{const n=+[...m].map(c=>SUP[c]).join('');return `<button class="note-ref" data-note="${n}" aria-label="Abrir nota ${n}">${n}</button>`})}
function openNote(n,bookId=state.book){const src=bookId==='genesis'?state.genesisData:state.data;const note=src&&src.notes.find(x=>x.id===n);if(!note)return;if(!state.opened.includes(n)){state.opened.push(n);localStorage.setItem('dtb:opened',JSON.stringify(state.opened))}const saved=state.saved.some(x=>x.type==='note'&&x.key==n),interpretive=(note.evidence||[]).some(e=>e[0]==='D'||e==='E2'||e==='E3');$('#decodeContent').innerHTML=`<p class="decode-kicker">VERBUM REVELANS · ${String(n).padStart(2,'0')} · ${BOOKS[bookId].name.toUpperCase()} ${note.chapter}</p><div class="decode-hebrew">${note.hebrew||''}</div><h2 class="decode-title">${note.title}</h2><div>${(note.evidence||[]).map(e=>`<span class="evidence ${e[0]==='D'?'d':''}">${e}</span>`).join('')}</div>${interpretive?'<p class="review-flag"><b>LECTURA EN DISCUSIÓN</b><span>Incluye hipótesis o interpretación editorial. Se conserva abierta a revisión.</span></p>':'<p class="review-flag verified"><b>BASE TEXTUAL</b><span>La nota se apoya principalmente en evidencia directa del texto.</span></p>'}<h3 class="layer-label">CAMPO LINGÜÍSTICO + DECISIÓN CODI</h3><p class="decode-body">${note.body}</p><p class="source-line">Fuente base: OSHB / WLC. Las etiquetas separan evidencia e interpretación.</p><div class="decode-actions"><button class="primary" id="saveNote">${saved?'Guardado':'Guardar lectura'}</button><button class="secondary" id="backVerse">Volver al versículo</button></div>`;$('#decodeDialog').showModal();$('#saveNote').onclick=()=>toggleNote(note);$('#backVerse').onclick=()=>$('#decodeDialog').close();renderHome()}
function toggleNote(note){const i=state.saved.findIndex(x=>x.type==='note'&&x.key==note.id);if(i>=0)state.saved.splice(i,1);else state.saved.push({type:'note',key:note.id,title:note.title,text:note.body});save();$('#decodeDialog').close()}
function toggleVerse(key,b){const i=state.saved.findIndex(x=>x.type==='verse'&&x.key===key);if(i>=0)state.saved.splice(i,1);else{const [bookId,c,n]=key.split(':');const v=state.data.chapters[c].find(x=>x.number===n),text=(v.text||v.hebrew||'').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'');state.saved.push({type:'verse',key,title:`${BOOKS[bookId].name} ${c}:${n}`,text})}save();b.classList.toggle('saved')}
function openVerseActions(key){const [bookId,c,n]=key.split(':'),bk=BOOKS[bookId],v=state.data.chapters[c].find(x=>x.number===n),source=v.text||v.hebrew||'',clean=source.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'');$('#verseActionContent').innerHTML=`<p class="decode-kicker">${bk.name.toUpperCase()} ${c}:${n}</p><h2 class="verse-sheet-title">${clean}</h2><div class="verse-action-grid"><button id="sheetSave">◇<span>Guardar</span></button><button id="sheetDecode">◉<span>Abrir CODY</span></button><button id="sheetNote">＋<span>Anotar</span></button><button id="sheetShare">↗<span>Compartir</span></button></div><p class="source-line">Tocá fuera del panel para volver a la lectura.</p>`;$('#verseDialog').showModal();$('#sheetSave').onclick=()=>{toggleVerse(key,$(`[data-save-verse="${key}"]`));$('#verseDialog').close()};$('#sheetDecode').onclick=()=>{const match=[...source.matchAll(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g)][0];$('#verseDialog').close();match?openNote(+[...match[0]].map(x=>SUP[x]).join('')):showView('cody')};$('#sheetNote').onclick=()=>{$('#verseDialog').close();showView('saved');$('#personalNote').value=`${bk.name} ${c}:${n} — `;$('#personalNote').focus()};$('#sheetShare').onclick=async()=>{const text=`${bk.name} ${c}:${n} — ${clean}`;if(navigator.share)await navigator.share({title:`${bk.name} ${c}:${n}`,text});else{await navigator.clipboard.writeText(text);$('#sheetShare span').textContent='Copiado'}}}
function renderTerms(filter='featured'){const bk=BOOKS[state.book];if(filter==='featured'&&state.book!=='genesis')filter='all';const featured=[1,3,5,6,9,14,16,22,28,30,32,35,36,41,42,48,51,58,63,67,70,72,73,76,77,81,83,87,90],items=filter==='featured'?featured.map(n=>state.data.notes.find(a=>a.id===n)).filter(Boolean):filter==='all'?state.data.notes:state.data.notes.filter(x=>x.chapter===+filter);$('#termGrid').innerHTML=items.map(x=>`<button class="term-card" data-card-note="${x.id}"><div class="hebrew">${x.hebrew||`${bk.name.toUpperCase()} ${x.chapter}`}</div><h3>${x.title}</h3><p>${x.teaser||x.body.slice(0,125)+'…'}</p><small>${(x.evidence||[]).join(' · ')||'LECTURA CODI'}</small></button>`).join('');$$('[data-card-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.cardNote))}
function renderSaved(){const el=$('#savedList');el.innerHTML=state.saved.length?state.saved.slice().reverse().map((x,i)=>`<article class="saved-item"><strong>${x.type==='verse'?x.title:x.type==='personal'?'NOTA PERSONAL':'VERBUM REVELANS'}</strong><p>${x.type==='note'?x.title:x.text}</p><button class="remove-save" data-remove="${state.saved.length-1-i}" aria-label="Eliminar">×</button></article>`).join(''):'<article class="saved-item"><p>Todavía no guardaste ninguna marca. Tocá ◇ junto a un versículo o guardá una decodificación CODY.</p></article>';$$('[data-remove]').forEach(b=>b.onclick=()=>{state.saved.splice(+b.dataset.remove,1);save();renderSaved();renderHome()})}
function renderHome(){if(!state.data)return;const bk=BOOKS[state.book];const day=(new Date().getDate()-1)%state.data.notes.length,n=state.data.notes[day];$('#dailyCard').innerHTML=`<div class="daily-hebrew">${n.hebrew||`${bk.name.toUpperCase()} ${n.chapter}`}</div><div><h2>${n.title}</h2><p>${n.teaser||n.body.slice(0,120)+'…'}</p></div>`;$('#dailyCard').onclick=()=>openNote(n.id);const done=state.steps.length,p=Math.round(done/journey.length*100),translated=Object.values(state.data.chapters).flat().filter(v=>v.text).length,readChapters=new Set(state.read.filter(id=>id.startsWith('v-'+state.book+'-')).map(id=>id.replace('v-'+state.book+'-','').split('-')[0])).size;$('#progressPercent').textContent=p+'%';$('.ring').style.setProperty('--p',p+'%');$('#readingFill').style.width=Math.max(4,Math.min(100,state.read.length/translated*100))+'%';$('#continueChapter').textContent=state.chapter;$('#homeChapterCount')&&($('#homeChapterCount').textContent=readChapters);$('#homeProgressLabel')&&($('#homeProgressLabel').textContent='PROGRESO DE '+bk.name.toUpperCase());$('#homeProgressFill')&&($('#homeProgressFill').style.width=Math.max(4,Math.min(100,readChapters/30*100))+'%');$('#stepPreview').innerHTML=`<strong>${done===7?'Recorrido completo':journey[done][0]}</strong><small>${done===7?'Volvé a atravesarlo desde otra palabra.':journey[done][2]}</small>`;$('#readStat').textContent=state.read.length;$('#decodedStat').textContent=state.opened.length;$('#savedStat').textContent=state.saved.length}
