function showScratchCollection(){const s=$('#gameStage');s.innerHTML=`<div class="game-head"><small>LEVANTAR EL VELO · GÉNESIS 1–9</small><h2>Elegí qué traducción querés raspar</h2><p>Nueve capítulos. Nueve palabras que parecen conocidas hasta que levantás la superficie.</p></div><div class="scratch-collection">${scratchDeck.map((card,i)=>`<button data-scratch-card="${i}"><small>GÉNESIS ${card.chapter}</small><b>${card.cover}</b><span>Raspar →</span></button>`).join('')}</div>`;$$('[data-scratch-card]').forEach(b=>b.onclick=()=>openScratchCard(+b.dataset.scratchCard))}
function openScratchCard(index){scratchIndex=index;const card=scratchDeck[index],s=$('#gameStage');s.innerHTML=`<button class="scratch-back" id="scratchBack">‹ Ver las nueve</button><div class="game-head"><small>GÉNESIS ${card.chapter} · ${index+1}/${scratchDeck.length}</small><h2>${card.title}</h2><p>Raspá con el dedo hasta levantar la lectura heredada.</p></div><div class="scratch-wrap"><div class="scratch-reveal"><small class="scratch-level">CODI ANALIZA · ${card.level}</small><b>${card.hebrew}</b><strong>${card.answer}</strong><p>${card.body}</p></div><canvas id="scratchCanvas"></canvas></div><div class="scratch-nav"><button id="scratchPrev">‹ Anterior</button><button id="scratchNext">Siguiente ›</button></div>`;setupScratch();$('#scratchBack').onclick=showScratchCollection;$('#scratchPrev').onclick=()=>openScratchCard((index-1+scratchDeck.length)%scratchDeck.length);$('#scratchNext').onclick=()=>openScratchCard((index+1)%scratchDeck.length)}
function setupScratch(){const c=$('#scratchCanvas'),box=c.parentElement,r=box.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;c.style.width=r.width+'px';c.style.height=r.height+'px';const x=c.getContext('2d');x.scale(d,d);const g=x.createLinearGradient(0,0,r.width,r.height);g.addColorStop(0,'#8b6a32');g.addColorStop(.5,'#e0bd68');g.addColorStop(1,'#765323');x.fillStyle=g;x.fillRect(0,0,r.width,r.height);x.fillStyle='#24170f';x.font='600 14px system-ui';x.textAlign='center';x.fillText('RASPÁ PARA REVELAR',r.width/2,r.height/2);let down=false,last=null;const draw=e=>{if(!down)return;const p=e.touches?.[0]||e,q=c.getBoundingClientRect(),nx=p.clientX-q.left,ny=p.clientY-q.top;x.globalCompositeOperation='destination-out';x.lineWidth=38;x.lineCap='round';x.beginPath();if(last)x.moveTo(last[0],last[1]);x.lineTo(nx,ny);x.stroke();last=[nx,ny]};c.onpointerdown=e=>{down=true;last=null;c.setPointerCapture(e.pointerId);draw(e)};c.onpointermove=draw;c.onpointerup=()=>{down=false;last=null}}
function search(q){q=q.trim().toLowerCase();if(!q){$('#searchResults').innerHTML='';return}const bk=BOOKS[state.book];let out=[];for(const [c,vs] of Object.entries(state.data.chapters))for(const v of vs)if((v.text||'').toLowerCase().includes(q))out.push({c,v});$('#searchResults').innerHTML=out.slice(0,20).map(x=>`<button class="search-result" data-hit="${x.c}:${x.v.number}"><strong>${bk.name} ${x.c}:${x.v.number}</strong><br>${x.v.text}</button>`).join('')||'<p>Sin resultados en la traducción CODI disponible.</p>';$$('[data-hit]').forEach(b=>b.onclick=()=>{const [c,...rest]=b.dataset.hit.split(':');const n=rest.join(':');state.chapter=+c;render();$('#searchDialog').close();showView('reader');setTimeout(()=>$('#v-'+state.book+'-'+c+'-'+n)?.scrollIntoView({behavior:'smooth',block:'center'}),80)})}
function relabelCodi(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())if(n.nodeValue.includes('CODY'))n.nodeValue=n.nodeValue.replaceAll('CODY','CODI');document.title=document.title.replaceAll('CODY','CODI')}
new MutationObserver(relabelCodi).observe(document.body,{subtree:true,childList:true,characterData:true});
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});
init().catch(e=>{console.error(e);$('#verses').innerHTML='<p>No se pudo cargar el texto.</p>'});
